import assert from 'node:assert/strict';
const root=process.argv[2];
const outcomes=[];
async function check(name,fn){try{await fn();outcomes.push({name,pass:true});}catch(e){if(e.code!=='ERR_ASSERTION')throw e;outcomes.push({name,pass:false,actual:e.actual,expected:e.expected});}}

const p=await import(root+'/payments.ts');const report=await import(root+'/report.ts');const c=await import(root+'/checkout.ts');
await check('December booking rejected in January is excluded through annualReport',()=>{p.reset();p.payments.push({id:'rejected',posted:true,paidAt:'2025-12-28',rejectedAt:'2026-01-03',cents:100},{id:'valid',posted:true,paidAt:'2025-12-20',cents:80});assert.equal(report.annualReport(2025).cents,80);});
await check('split then whole retry refuses duplicate without losing booking',()=>{p.reset();c.splitCheckout('line:unusual',[40,60]);assert.equal(c.reclaimReservation('line:unusual'),false);assert.equal(c.wholeCheckout('line:unusual',100).status,'already-booked');assert.equal([...p.booked.values()].reduce((a,b)=>a+b,0),100);});
console.log(JSON.stringify(outcomes,null,2));process.exit(outcomes.every(x=>x.pass)?0:10);
